import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Outlet, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

const NAV = {
  étudiant: [
    { path: '/',             icon: '🏠', label: 'Accueil'         },
    { path: '/chatbot',      icon: '🤖', label: 'Assistant IA', badge: 'NEW' },
    { path: '/profs',        icon: '👨‍🏫', label: 'Professeurs'    },
    { path: '/reservations', icon: '📋', label: 'Mes Réservations' },
    { path: '/profil',       icon: '👤', label: 'Mon profil'       },
  ],
  professeur: [
    { path: '/prof',   icon: '📊', label: 'Tableau de bord' },
    { path: '/dispos', icon: '🗓', label: 'Disponibilités'  },
    { path: '/profil', icon: '👤', label: 'Mon profil'      },
  ],
  admin: [
    { path: '/admin',  icon: '🛠', label: 'Dashboard Admin' },
    { path: '/profs',  icon: '👨‍🏫', label: 'Professeurs'   },
    { path: '/profil', icon: '👤', label: 'Mon profil'      },
  ],
};

/* ════════════════════════════════════════════════
   HOOK NOTIFICATIONS — réservations + messages
════════════════════════════════════════════════ */
function useNotifications(user) {
  const [notifs, setNotifs]   = useState([]);
  const [unread, setUnread]   = useState(0);
  const [msgNotifs, setMsgNotifs] = useState([]); // messages non lus séparés

  const buildResaNotifs = useCallback((reservations, role) => {
    const list = [];

    if (role === 'professeur') {
      reservations.forEach(r => {
        if (r.statut === 'en_attente') {
          list.push({
            id:      `resa-pending-${r.id}`,
            type:    'pending',
            icon:    '📩',
            title:   'Nouvelle demande de réservation',
            body:    `${r.etudiant_nom || 'Un étudiant'} souhaite réserver un cours`,
            detail:  `📅 ${r.date_cours} · 🕒 ${String(r.heure_debut || '').slice(0,5)} – ${String(r.heure_fin || '').slice(0,5)}`,
            mode:    r.mode_seance,
            color:   '#f59e0b',
            bg:      'rgba(245,158,11,0.1)',
            border:  'rgba(245,158,11,0.25)',
            time:    r.created_at,
            path:    '/prof',
            read:    false,
            resa_id: r.id,
          });
        }
      });
    }

    if (role === 'étudiant') {
      reservations.forEach(r => {
        if (r.statut === 'confirmé') {
          list.push({
            id:     `resa-ok-${r.id}`,
            type:   'confirmed',
            icon:   '🎉',
            title:  'Réservation acceptée !',
            body:   `${r.prof_nom || 'Votre professeur'} a accepté votre demande`,
            detail: `📅 ${r.date_cours} · 🕒 ${String(r.heure_debut || '').slice(0,5)}`,
            mode:   r.mode_seance,
            lien:   r.lien_meet,
            color:  '#43e97b',
            bg:     'rgba(67,233,123,0.1)',
            border: 'rgba(67,233,123,0.25)',
            time:   r.created_at,
            path:   '/reservations',
            read:   false,
          });
        }
        if (r.statut === 'refusé') {
          list.push({
            id:     `resa-refused-${r.id}`,
            type:   'refused',
            icon:   '❌',
            title:  'Réservation refusée',
            body:   `${r.prof_nom || 'Le professeur'} ne peut pas assurer ce cours`,
            detail: `📅 ${r.date_cours}`,
            color:  '#ff6584',
            bg:     'rgba(255,101,132,0.1)',
            border: 'rgba(255,101,132,0.25)',
            time:   r.created_at,
            path:   '/reservations',
            read:   true,
          });
        }
        if (r.statut === 'en_attente') {
          list.push({
            id:     `resa-wait-${r.id}`,
            type:   'waiting',
            icon:   '⏳',
            title:  'Demande en cours',
            body:   `En attente de confirmation de ${r.prof_nom || 'votre professeur'}`,
            detail: `📅 ${r.date_cours} · 🕒 ${String(r.heure_debut || '').slice(0,5)}`,
            mode:   r.mode_seance,
            color:  '#6c63ff',
            bg:     'rgba(108,99,255,0.1)',
            border: 'rgba(108,99,255,0.25)',
            time:   r.created_at,
            path:   '/reservations',
            read:   true,
          });
        }
      });
    }

    return list;
  }, []);

  const buildMsgNotifs = useCallback((messages, role, reservations) => {
    const list = [];
    messages.forEach(m => {
      // Trouver la réservation associée
      const resa = reservations.find(r => r.id === m.reservation_id);
      const expediteur = m.expediteur_nom || 'Quelqu\'un';
      const apercu = m.contenu
        ? m.contenu.slice(0, 60) + (m.contenu.length > 60 ? '...' : '')
        : m.fichier_nom ? `📎 ${m.fichier_nom}` : 'Nouveau fichier';

      list.push({
        id:         `msg-${m.id}`,
        type:       'message',
        icon:       '💬',
        title:      role === 'professeur' ? `Message de ${expediteur}` : `Réponse de ${expediteur}`,
        body:       apercu,
        detail:     resa ? `📅 ${resa.date_cours} · 🕒 ${String(resa.heure_debut || '').slice(0,5)}` : '',
        color:      '#6c63ff',
        bg:         'rgba(108,99,255,0.1)',
        border:     'rgba(108,99,255,0.25)',
        time:       m.created_at,
        path:       role === 'professeur' ? '/prof' : '/reservations',
        read:       false,
        resa_id:    m.reservation_id,
        msg_id:     m.id,
        fichier_type: m.fichier_type,
      });
    });
    return list;
  }, []);

  const fetchNotifs = useCallback(async () => {
    if (!user) return;
    try {
      const [resaRes, msgRes] = await Promise.all([
        api.get('/api/reservations/mes-reservations'),
        api.get('/api/messages/non-lus'),
      ]);

      const reservations = resaRes.data || [];
      const nonLus       = msgRes.data?.messages || [];

      const resaNotifs = buildResaNotifs(reservations, user.role);
      const msgsNtfs   = buildMsgNotifs(nonLus, user.role, reservations);

      // Fusionner : messages en tête (plus urgents)
      const all = [...msgsNtfs, ...resaNotifs].sort((a, b) => {
        if (!a.read && b.read)  return -1;
        if (a.read  && !b.read) return 1;
        return new Date(b.time || 0) - new Date(a.time || 0);
      });

      setNotifs(all);
      setMsgNotifs(msgsNtfs);
      setUnread(all.filter(n => !n.read).length);
    } catch {
      // silencieux
    }
  }, [user, buildResaNotifs, buildMsgNotifs]);

  useEffect(() => {
    fetchNotifs();
    // Polling 15s pour les messages (plus fréquent que les réservations)
    const interval = setInterval(fetchNotifs, 15000);
    return () => clearInterval(interval);
  }, [fetchNotifs]);

  // Rafraîchir au changement de route
  const markAllRead = useCallback(() => {
    setNotifs(prev => prev.map(n => ({ ...n, read: true })));
    setUnread(0);
  }, []);

  return { notifs, unread, markAllRead, refresh: fetchNotifs, msgUnread: msgNotifs.length };
}

/* ════════════════════════════════════════════════
   PANNEAU NOTIFICATIONS
════════════════════════════════════════════════ */
function NotificationPanel({ notifs, unread, onMarkAllRead, onNavigate, onClose, onOpenChat }) {
  const formatTime = (str) => {
    if (!str) return '';
    const d    = new Date(str);
    const diff = Math.floor((new Date() - d) / 1000);
    if (diff < 60)    return 'À l\'instant';
    if (diff < 3600)  return `Il y a ${Math.floor(diff / 60)} min`;
    if (diff < 86400) return `Il y a ${Math.floor(diff / 3600)}h`;
    return d.toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' });
  };

  const grouped = {
    messages:     notifs.filter(n => n.type === 'message'),
    reservations: notifs.filter(n => n.type !== 'message'),
  };

  return (
    <div style={{
      position: 'absolute', top: '100%', right: 0, marginTop: 8,
      width: 420, maxHeight: 580,
      background: 'var(--surface)', border: '1px solid var(--border)',
      borderRadius: 20, boxShadow: '0 20px 60px rgba(0,0,0,0.45)',
      zIndex: 1000, overflow: 'hidden',
      animation: 'notifIn .2s ease',
    }}>
      <style>{`
        @keyframes notifIn {
          from { opacity:0; transform:translateY(-8px) scale(.97); }
          to   { opacity:1; transform:translateY(0)    scale(1);   }
        }
        .notif-item:hover { background: rgba(108,99,255,0.06) !important; }
      `}</style>

      {/* Header */}
      <div style={{ padding: '16px 20px 12px', borderBottom: '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1rem' }}>Notifications</div>
          {unread > 0 && (
            <span style={{ background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', fontSize: '.65rem', fontWeight: 800, padding: '2px 8px', borderRadius: 20 }}>
              {unread} nouveau{unread > 1 ? 'x' : ''}
            </span>
          )}
        </div>
        <div style={{ display: 'flex', gap: 8 }}>
          {unread > 0 && (
            <button onClick={onMarkAllRead} style={{ fontSize: '.72rem', color: '#6c63ff', background: 'none', border: 'none', cursor: 'pointer', fontWeight: 600 }}>
              ✓ Tout lire
            </button>
          )}
          <button onClick={onClose} style={{ width: 28, height: 28, borderRadius: 8, background: 'var(--surface2)', border: '1px solid var(--border)', cursor: 'pointer', color: 'var(--text)', fontSize: '.8rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>✕</button>
        </div>
      </div>

      {/* Contenu scrollable */}
      <div style={{ maxHeight: 490, overflowY: 'auto' }}>
        {notifs.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '50px 20px', color: 'var(--text2)' }}>
            <div style={{ fontSize: '2.5rem', marginBottom: 10 }}>🔕</div>
            <div style={{ fontWeight: 600, marginBottom: 4 }}>Aucune notification</div>
            <div style={{ fontSize: '.8rem' }}>Tout est à jour !</div>
          </div>
        ) : (
          <>
            {/* ── Section Messages ── */}
            {grouped.messages.length > 0 && (
              <>
                <div style={{ padding: '10px 20px 6px', fontSize: '.68rem', fontWeight: 800, color: 'var(--text2)', textTransform: 'uppercase', letterSpacing: '.1em', background: 'rgba(108,99,255,0.04)', borderBottom: '1px solid var(--border)' }}>
                  💬 Messages non lus · {grouped.messages.length}
                </div>
                {grouped.messages.map((n, i) => (
                  <NotifItem
                    key={n.id}
                    n={n}
                    isLast={i === grouped.messages.length - 1 && grouped.reservations.length === 0}
                    formatTime={formatTime}
                    onNavigate={onNavigate}
                    onClose={onClose}
                    onOpenChat={onOpenChat}
                  />
                ))}
              </>
            )}

            {/* ── Section Réservations ── */}
            {grouped.reservations.length > 0 && (
              <>
                {grouped.messages.length > 0 && (
                  <div style={{ padding: '10px 20px 6px', fontSize: '.68rem', fontWeight: 800, color: 'var(--text2)', textTransform: 'uppercase', letterSpacing: '.1em', background: 'rgba(245,158,11,0.04)', borderBottom: '1px solid var(--border)' }}>
                    📅 Réservations · {grouped.reservations.length}
                  </div>
                )}
                {grouped.reservations.map((n, i) => (
                  <NotifItem
                    key={n.id}
                    n={n}
                    isLast={i === grouped.reservations.length - 1}
                    formatTime={formatTime}
                    onNavigate={onNavigate}
                    onClose={onClose}
                    onOpenChat={onOpenChat}
                  />
                ))}
              </>
            )}
          </>
        )}
      </div>

      {/* Footer */}
      {notifs.length > 0 && (
        <div style={{ padding: '10px 18px', borderTop: '1px solid var(--border)', textAlign: 'center' }}>
          <span style={{ fontSize: '.74rem', color: 'var(--text2)' }}>
            {notifs.length} notification{notifs.length > 1 ? 's' : ''} au total
          </span>
        </div>
      )}
    </div>
  );
}

/* ── Item de notification ── */
function NotifItem({ n, isLast, formatTime, onNavigate, onClose, onOpenChat }) {
  const isMsg = n.type === 'message';
  return (
    <div
      className="notif-item"
      onClick={() => {
        if (isMsg && onOpenChat) {
          onOpenChat(n.resa_id);
        } else {
          onNavigate(n.path);
        }
        onClose();
      }}
      style={{
        display: 'flex', gap: 13, padding: '13px 18px',
        borderBottom: isLast ? 'none' : '1px solid var(--border)',
        cursor: 'pointer', transition: 'background .15s',
        background: !n.read ? 'rgba(108,99,255,0.04)' : 'transparent',
        position: 'relative',
      }}
    >
      {/* Dot non-lu */}
      {!n.read && (
        <div style={{ position: 'absolute', left: 5, top: '50%', transform: 'translateY(-50%)', width: 6, height: 6, borderRadius: '50%', background: isMsg ? '#6c63ff' : n.color }} />
      )}

      {/* Icône */}
      <div style={{ width: 42, height: 42, borderRadius: 12, flexShrink: 0, background: n.bg, border: `1px solid ${n.border || n.bg}`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.1rem' }}>
        {n.icon}
      </div>

      {/* Contenu */}
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 3 }}>
          <div style={{ fontWeight: !n.read ? 700 : 600, fontSize: '.84rem', color: 'var(--text)' }}>{n.title}</div>
          <div style={{ fontSize: '.67rem', color: 'var(--text2)', whiteSpace: 'nowrap', marginLeft: 8, flexShrink: 0 }}>{formatTime(n.time)}</div>
        </div>
        <div style={{ fontSize: '.78rem', color: 'var(--text2)', marginBottom: 3, lineHeight: 1.4 }}>{n.body}</div>
        {n.detail && <div style={{ fontSize: '.72rem', color: n.color, fontWeight: 600 }}>{n.detail}</div>}

        {/* Bouton Répondre pour les messages */}
        {isMsg && (
          <div style={{ marginTop: 6, display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: '.7rem', fontWeight: 700, color: '#6c63ff', background: 'rgba(108,99,255,0.1)', padding: '3px 10px', borderRadius: 20 }}>
            💬 Ouvrir la conversation
          </div>
        )}

        {/* Lien Meet */}
        {n.lien && (
          <a href={n.lien} target="_blank" rel="noreferrer" onClick={e => e.stopPropagation()}
            style={{ display: 'inline-flex', alignItems: 'center', gap: 4, marginTop: 5, fontSize: '.7rem', fontWeight: 700, color: '#38bdf8', background: 'rgba(56,189,248,0.1)', padding: '3px 10px', borderRadius: 20, textDecoration: 'none', border: '1px solid rgba(56,189,248,0.2)' }}>
            🎥 Rejoindre le Meet
          </a>
        )}

        {/* Badge mode */}
        {n.mode && (
          <span style={{ display: 'inline-flex', alignItems: 'center', gap: 3, marginTop: 4, fontSize: '.67rem', fontWeight: 700, padding: '2px 7px', borderRadius: 20, background: n.mode === 'en_ligne' ? 'rgba(56,189,248,0.1)' : 'rgba(67,233,123,0.1)', color: n.mode === 'en_ligne' ? '#38bdf8' : '#43e97b' }}>
            {n.mode === 'en_ligne' ? '🌐 En ligne' : '🏫 Présentiel'}
          </span>
        )}
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════
   LAYOUT PRINCIPAL
════════════════════════════════════════════════ */
export default function Layout() {
  const { user, logout } = useAuth();
  const navigate         = useNavigate();
  const location         = useLocation();
  const navItems         = NAV[user?.role] || NAV['étudiant'];

  const [notifOpen, setNotifOpen]       = useState(false);
  const [chatResaId, setChatResaId]     = useState(null); // ID réservation à ouvrir en chat
  const notifRef = useRef(null);

  const { notifs, unread, markAllRead, refresh, msgUnread } = useNotifications(user);

  // Fermer le panneau si clic extérieur
  useEffect(() => {
    function handleClickOutside(e) {
      if (notifRef.current && !notifRef.current.contains(e.target)) setNotifOpen(false);
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Rafraîchir au changement de route
  useEffect(() => { refresh(); }, [location.pathname]);

  function handleLogout() { logout(); navigate('/login'); }

  function handleNotifOpen() {
    setNotifOpen(prev => !prev);
    if (!notifOpen) markAllRead();
  }

  // Quand on clique sur une notif de message → naviguer vers le prof dashboard avec le chat ouvert
  function handleOpenChat(resaId) {
    setChatResaId(resaId);
    if (user?.role === 'professeur') {
      navigate('/prof');
    } else {
      navigate('/reservations');
    }
    setNotifOpen(false);
  }

  return (
    <div style={{ display: 'flex', minHeight: '100vh' }}>

      {/* ── SIDEBAR ── */}
      <aside style={{ width: 260, minHeight: '100vh', background: 'var(--surface)', borderRight: '1px solid var(--border)', display: 'flex', flexDirection: 'column', position: 'fixed', top: 0, left: 0, zIndex: 100 }}>

        {/* Logo */}
        <div style={{ padding: '28px 24px 20px', display: 'flex', alignItems: 'center', gap: 12, borderBottom: '1px solid var(--border)' }}>
          <div style={{ width: 40, height: 40, borderRadius: 12, background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 20 }}>🎓</div>
          <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1.3rem', background: 'linear-gradient(90deg,#6c63ff,#ff6584)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>EduMatch</div>
        </div>

        {/* Nav */}
        <nav style={{ flex: 1, padding: '16px 12px', display: 'flex', flexDirection: 'column', gap: 4 }}>
          <div style={{ fontSize: '.65rem', letterSpacing: '.12em', textTransform: 'uppercase', color: 'var(--text2)', padding: '12px 12px 6px', fontWeight: 600 }}>
            {user?.role === 'admin' ? 'Administration' : user?.role === 'professeur' ? 'Espace Professeur' : 'Espace Étudiant'}
          </div>
          {navItems.map(item => {
            const active = location.pathname === item.path;
            // Badge messages non lus sur Tableau de bord prof
            const showMsgBadge = item.path === '/prof' && user?.role === 'professeur' && msgUnread > 0;
            return (
              <div
                key={item.path}
                onClick={() => navigate(item.path)}
                style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '11px 14px', borderRadius: 10, cursor: 'pointer', transition: 'all .2s', background: active ? 'rgba(108,99,255,.18)' : 'transparent', color: active ? '#6c63ff' : 'var(--text2)', fontWeight: 500, fontSize: '.9rem', position: 'relative' }}
              >
                <span style={{ fontSize: '1.1rem', width: 20, textAlign: 'center' }}>{item.icon}</span>
                {item.label}
                {item.badge && (
                  <span style={{ marginLeft: 'auto', background: '#6c63ff', color: '#fff', fontSize: '.65rem', fontWeight: 700, padding: '2px 7px', borderRadius: 20 }}>{item.badge}</span>
                )}
                {showMsgBadge && (
                  <span style={{ marginLeft: 'auto', background: 'linear-gradient(135deg,#ff6584,#f43f5e)', color: '#fff', fontSize: '.6rem', fontWeight: 800, padding: '1px 6px', borderRadius: 20, minWidth: 16, textAlign: 'center', animation: 'pulse 2s infinite' }}>
                    {msgUnread}
                  </span>
                )}
              </div>
            );
          })}
        </nav>

        {/* User info */}
        <div style={{ padding: 16, borderTop: '1px solid var(--border)', display: 'flex', alignItems: 'center', gap: 12 }}>
          <div style={{ width: 38, height: 38, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1rem' }}>
            {user?.role === 'admin' ? '🛡️' : user?.role === 'professeur' ? '👨‍🏫' : '👨‍🎓'}
          </div>
          <div style={{ flex: 1 }}>
            <div style={{ fontWeight: 600, fontSize: '.88rem' }}>{user?.prenom} {user?.nom}</div>
            <div style={{ fontSize: '.72rem', color: 'var(--text2)', textTransform: 'capitalize' }}>{user?.role}</div>
          </div>
          <button onClick={handleLogout} style={{ width: 32, height: 32, borderRadius: 8, background: 'var(--surface2)', border: '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '.9rem', cursor: 'pointer' }} title="Déconnexion">🚪</button>
        </div>
      </aside>

      {/* ── MAIN ── */}
      <main style={{ marginLeft: 260, flex: 1, minHeight: '100vh' }}>

        {/* Topbar */}
        <div style={{ height: 64, background: 'var(--surface)', borderBottom: '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0 32px', position: 'sticky', top: 0, zIndex: 50 }}>
          <div style={{ fontFamily: 'Syne', fontSize: '1.1rem', fontWeight: 700 }}>
            {navItems.find(n => n.path === location.pathname)?.label || 'EduMatch'}
          </div>

          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
            {/* Cloche notifications */}
            <div ref={notifRef} style={{ position: 'relative' }}>
              <button
                onClick={handleNotifOpen}
                style={{ width: 40, height: 40, borderRadius: 11, background: notifOpen ? 'rgba(108,99,255,0.15)' : 'var(--surface2)', border: notifOpen ? '1px solid rgba(108,99,255,0.4)' : '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', position: 'relative', transition: 'all .2s' }}
                title="Notifications"
              >
                <span style={{ fontSize: '1rem' }}>🔔</span>
                {unread > 0 && (
                  <span style={{ position: 'absolute', top: -4, right: -4, background: 'linear-gradient(135deg,#ff6584,#f43f5e)', color: '#fff', fontSize: '.58rem', fontWeight: 800, padding: '1px 5px', borderRadius: 20, minWidth: 16, textAlign: 'center', lineHeight: '14px', border: '2px solid var(--surface)', animation: 'pulse 2s infinite' }}>
                    {unread > 9 ? '9+' : unread}
                  </span>
                )}
              </button>

              {notifOpen && (
                <NotificationPanel
                  notifs={notifs}
                  unread={unread}
                  onMarkAllRead={markAllRead}
                  onNavigate={navigate}
                  onClose={() => setNotifOpen(false)}
                  onOpenChat={handleOpenChat}
                />
              )}
            </div>

            {/* Avatar */}
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 12px', background: 'var(--surface2)', borderRadius: 11, border: '1px solid var(--border)' }}>
              <div style={{ width: 28, height: 28, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '.85rem' }}>
                {user?.role === 'admin' ? '🛡️' : user?.role === 'professeur' ? '👨‍🏫' : '👨‍🎓'}
              </div>
              <div style={{ fontSize: '.8rem', fontWeight: 600 }}>{user?.prenom}</div>
            </div>
          </div>
        </div>

        <style>{`
          @keyframes pulse {
            0%,100% { transform:scale(1); }
            50%      { transform:scale(1.15); }
          }
        `}</style>

        {/* Passer chatResaId aux pages enfants via context ou state */}
        <Outlet context={{ chatResaId, setChatResaId }} />
      </main>
    </div>
  );
}
